function pathKey (path) {
  assert.ok(typeof path === "string" && /^[A-Za-z0-9_.-]+(?:\/[A-Za-z0-9_.-]+)*$/.test(path), "repository-relative path");
  assert.ok(!path.split("/").some(part => part === "." || part === ".."), "no traversal"); return path;
}
function decoded (input) {
  assert.ok(typeof input === "string" || Buffer.isBuffer(input));
  const text = typeof input === "string" ? input : new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(input);
  assert.ok(!text.startsWith("\uFEFF") && !text.includes("\0"));
  assert.equal(Buffer.from(text).toString("utf8"), text, "lossless Unicode");
  const lf = text.replace(/\r\n/g, "\n"); assert.ok(!lf.includes("\r"));
  assert.ok(!text.includes("\r\n") || !/(?<!\r)\n/.test(text), "uniform physical EOL");
  assert.ok(lf.endsWith("\n") && !lf.endsWith("\n\n")); assert.doesNotMatch(lf, /[ \t]+$/m);
  return { lf, crlf: text.includes("\r\n"), buffer: Buffer.isBuffer(input) };
}
